package ar.com.liftmanager.controller;
import ar.com.liftmanager.dto.ApiDtos.*;import ar.com.liftmanager.service.VisitService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/visits") public class VisitController {private final VisitService service;public VisitController(VisitService s){service=s;}@GetMapping public List<VisitView> list(){return service.list();}@PostMapping public VisitView create(@Valid @RequestBody VisitRequest r){return service.create(r);}@PatchMapping("/{id}/start") public VisitView start(@PathVariable Long id){return service.start(id);}@PatchMapping("/{id}/complete") public VisitView complete(@PathVariable Long id,@Valid @RequestBody CompleteVisitRequest r){return service.complete(id,r);}}
